// Package whipbench holds the synthetic clips the publisher streams, embedded so the
// binary needs no files beside it. Everything else lives under internal/ and cmd/.
//
// The clips are regenerated by scripts/make-clips.sh, which records the exact ffmpeg
// command; they are committed so nobody needs ffmpeg to build or test.
package whipbench

import _ "embed"

// ClipVP8 is testdata/clip-vp8.ivf: 640x360, 30 fps, 4 s, a keyframe every 30 frames.
//
//go:embed testdata/clip-vp8.ivf
var ClipVP8 []byte

// ClipH264 is testdata/clip-h264.h264: the same picture as constrained-baseline H.264,
// Annex-B, one slice per frame, SPS and PPS before every IDR.
//
//go:embed testdata/clip-h264.h264
var ClipH264 []byte
